import subprocess, sys, time, json, os, base64
from playwright.sync_api import sync_playwright
R = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
SH = sys.argv[1] if len(sys.argv) > 1 else '/tmp'
srv = subprocess.Popen([sys.executable, '-m', 'http.server', '8734', '--directory', R], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL); time.sleep(1)
ok = True
def check(n, c):
    global ok
    print(('OK   ' if c else 'FAIL ') + n)
    if not c: ok = False
FX = R + '/tests/fixtures/beartrap/'
b64 = lambda n: base64.b64encode(open(FX + n, 'rb').read()).decode()
try:
    with sync_playwright() as p:
        br = p.chromium.launch(); pg = br.new_page(viewport={'width': 1600, 'height': 1100}, reduced_motion='reduce'); errs = []
        pg.on('pageerror', lambda e: errs.append(str(e))); pg.on('framenavigated', lambda f: print('NAV', f.url))
        pg.goto('http://localhost:8734/app/index.html'); pg.wait_for_timeout(800)
        check('a Weather tab sits right after Performance', pg.evaluate("()=>{const t=[...document.querySelectorAll('header .tab')].map(x=>x.dataset.t);return t.indexOf('wx')==t.indexOf('pf')+1}"))
        pg.click('[data-t=wx]'); pg.wait_for_timeout(300)
        check('without a map the page says so', 'No weather map yet' in pg.inner_text('#wx'))
        pg.evaluate("""async(b)=>{const f=(s,n)=>new File([Uint8Array.from(atob(s),c=>c.charCodeAt(0))],n);await __app.loadCam(f(b,'x.cam'))}""", b64('PSI_BEAR_TRAP_26.cam')); pg.wait_for_timeout(800)
        pg.evaluate("async(b)=>{await __app.loadFmap(new File([Uint8Array.from(atob(b),c=>c.charCodeAt(0))],'x.fmap'))}", b64('PSI_BEAR_TRAP_26.fmap')); pg.wait_for_timeout(700)
        pg.click('[data-t=kb]'); pg.wait_for_timeout(500)
        # the hourly maps of the flight: the campaign map stands for each hour
        pg.evaluate("()=>{const i=+document.querySelector('#fsel').value||0;const f=__app.CL[i].f;__app.wxKeys(f).forEach(k=>__app.WXS.set(k,__app.WX))}")
        pg.click('[data-t=wx]'); pg.wait_for_timeout(700)
        pg.wait_for_timeout(1500)
        print(errs[:3]); t = pg.inner_text('#wx'); print('  ', t[:260].replace('\n', ' | '))
        check('the weather is drawn over the Leaflet map of the Map page (zoomable)', pg.evaluate("()=>{const b=document.querySelector('#wxbox');return !!b&&!!b.querySelector('.leaflet-container')&&!!b.querySelector('.leaflet-control-zoom')}"))
        check('the cells are an overlay of the map', pg.locator('#wxbox img.wxcells').count() == 1)
        check('no Map-page buttons on the weather map (only the Time & altitude one)', pg.evaluate("()=>{const b=document.querySelector('#wxbox');return !b.querySelector('#mpfilb')&&!!b.querySelector('#wxpb')}"))
        check('six map modes', pg.locator('#wx [data-mode]').count() == 6)
        check('legend with the four conditions', all(w in t for w in ('Sunny', 'Fair', 'Poor', 'Inclement')))
        check('no wind barbs outside the Wind tab', pg.locator('#wxbox .wxbb').count() == 0)
        check('the time & altitude panel is on the map', pg.locator('#wxpp #wxms').count() == 1 and pg.locator('#wxlvs').count() == 0 and pg.locator('.wxl #wxpp').count() == 1)
        lv0 = pg.evaluate("()=>__app.wxPage.state().lv")
        check('the altitude slider is only in the Wind tab (not in the conditions tab)', pg.locator('#wxlvs').count() == 0 and pg.locator('#wxpp [data-lv]').count() == 0)
        check('time slider with DEP and TOT marks', 'DEP' in pg.inner_text('#wxpp') and 'TOT' in pg.inner_text('#wxpp'))
        check('airbases with ATIS', pg.locator('#wx .wxb').count() >= 2 and 'KT' in t)
        check('route table with a wind per steerpoint', pg.locator('#wx .wtbl tr').count() > 3)
        check('winds aloft: ten rows', pg.locator('#wx .wxw').count() == 10)
        src = lambda: pg.evaluate("()=>document.querySelector('#wxbox img.wxcells').src.length+':'+document.querySelector('#wxbox img.wxcells').src.slice(-80)")
        for m in ('wind', 'temp', 'press', 'cloud', 'vis', 'cond'):
            b = src(); pg.click('#wx [data-mode=%s]' % m); pg.wait_for_timeout(250)
            check('mode %s changes the overlay' % m, src() != b and pg.locator('#wxbox img.wxcells').count() == 1)
        pg.click('#wx [data-mode=wind]'); pg.wait_for_timeout(300)
        nb = pg.locator('#wxbox .wxbb').count(); print('  barbs', nb)
        check('the Wind tab draws wind barbs (not every cell)', 20 < nb < 400)
        pg.evaluate("()=>{const m=__app.wxPage.layer().map;m.setZoom(m.getZoom()+2)}"); pg.wait_for_timeout(500)
        nb2 = pg.locator('#wxbox .wxbb').count(); print('  barbs zoomed', nb2)
        check('zooming in changes how many barbs are drawn', nb2 != nb)
        check('Wind tab: the altitude is a slider with the 10 layers written over it, SFC to 50', pg.locator('#wxpp #wxlvs').count() == 1 and pg.locator('#wxlv .wxtk span').count() == 10 and 'SFC' in pg.inner_text('#wxlv') and '50' in pg.inner_text('#wxlv') and pg.locator('#wxpp [data-lv]').count() == 0)
        check('by default the layer follows the flight plan (auto)', lv0 is None and 'from the flight plan' in pg.inner_text('#wxpp').lower())
        a = pg.evaluate("()=>[...document.querySelectorAll('#wxbox .wxbb path')].slice(0,6).map(p=>p.getAttribute('d')).join('|')")
        pg.evaluate("()=>{const e=document.querySelector('#wxlvs');e.value=8;e.dispatchEvent(new Event('input'));e.dispatchEvent(new Event('change'))}"); pg.wait_for_timeout(400)
        check('another layer: the barbs change and the choice is kept', pg.evaluate("()=>[...document.querySelectorAll('#wxbox .wxbb path')].slice(0,6).map(p=>p.getAttribute('d')).join('|')") != a and pg.evaluate("()=>__app.wxPage.state().lv") == 8 and 'from the flight plan' not in pg.inner_text('#wxpp').lower())
        check('the selected layer is lit in the winds aloft', pg.locator('#wx .wxw.on').count() == 1 and pg.evaluate("()=>document.querySelector('#wx .wxw.on').dataset.lv") == '8')
        pg.click('#wxpp [data-auto]'); pg.wait_for_timeout(300)
        check('the flight plan button goes back to auto', pg.evaluate("()=>__app.wxPage.state().lv") is None)
        pg.click('#wx [data-mode=cond]'); pg.wait_for_timeout(300)
        pg.evaluate("()=>{const m=__app.wxPage.layer().map;m.fire('mousemove',{latlng:m.getCenter()})}"); pg.wait_for_timeout(200)
        check('hover shows the data of the cell', 'mbar' in pg.inner_text('#wxinfo') and 'visibility' in pg.inner_text('#wxinfo'))
        op0 = pg.evaluate("()=>document.querySelector('.leaflet-wxP-pane, .leaflet-pane.wxP')?.style.opacity || getComputedStyle(__app.wxPage.layer().map.getPane('wxP')).opacity")
        pg.evaluate("()=>{const e=document.querySelector('#wxop');e.value=30;e.dispatchEvent(new Event('input'));e.dispatchEvent(new Event('change'))}"); pg.wait_for_timeout(200)
        check('opacity slider: 30% dims the weather layer, the label and the state follow', pg.evaluate("()=>getComputedStyle(__app.wxPage.layer().map.getPane('wxP')).opacity") == '0.3' and '30%' in pg.inner_text('#wxpp') and pg.evaluate("()=>__app.wxPage.state().op") == 30 and float(op0) == 1.0)
        pg.click('#wx [data-mode=wind]'); pg.wait_for_timeout(300)
        pg.evaluate("()=>{const e=document.querySelector('#wxlvs');e.value=2;e.dispatchEvent(new Event('input'));e.dispatchEvent(new Event('change'))}"); pg.wait_for_timeout(400)
        check('opacity is kept when the layer or the mode changes', pg.evaluate("()=>getComputedStyle(__app.wxPage.layer().map.getPane('wxP')).opacity") == '0.3' and pg.locator('#wxop').input_value() == '30' and 'Surface' not in pg.inner_text('#wxlvp'))
        pg.evaluate("()=>{const e=document.querySelector('#wxop');e.value=100;e.dispatchEvent(new Event('input'));e.dispatchEvent(new Event('change'))}")
        pg.click('#wxpb'); pg.wait_for_timeout(300)
        check('the panel opens and closes', not pg.is_visible('#wxpp') and pg.evaluate("()=>__app.wxPage.state().open") is False)
        pg.click('#wxpb'); pg.wait_for_timeout(300)
        check('and opens again', pg.is_visible('#wxpp'))
        # the slider changes the hour shown
        mn = pg.evaluate("()=>+document.querySelector('#wxms').min")
        pg.evaluate("(v)=>{const s=document.querySelector('#wxms');s.value=v;s.dispatchEvent(new Event('input'));s.dispatchEvent(new Event('change'))}", mn)
        pg.wait_for_timeout(300)
        check('the time slider is kept', pg.evaluate("()=>__app.wxPage.state().ms") == mn)
        # Fill datacard: dimmed while the datacard holds the weather, lit when a field was typed, and it writes it back
        pg.click('[data-t=kb]'); pg.wait_for_timeout(300)
        pg.evaluate("()=>{__app.setField?__app.setField('atis','X'):0}")
        st = pg.evaluate("()=>{const b=document.querySelector('#wx [data-fill]');return b?b.className:null}"); print('  fill class', st)
        pg.click('[data-t=wx]'); pg.wait_for_timeout(500)
        check('Fill datacard button exists', pg.locator('#wx [data-fill]').count() == 1)
        cls = pg.evaluate("()=>document.querySelector('#wx [data-fill]').className")
        if 'nil' not in cls:
            pg.click('#wx [data-fill]'); pg.wait_for_timeout(500)
            check('after Fill the button is dimmed (the datacard holds the weather)', 'nil' in pg.evaluate("()=>document.querySelector('#wx [data-fill]').className"))
        else:
            check('the button is dimmed when the datacard already holds the weather', True)
        pg.screenshot(path=SH + '/weather.png', full_page=True)
        pg.click('[data-t=mp]'); pg.wait_for_timeout(800)
        check('leaving the page gives the map back to the Map page (no weather left on it)', pg.evaluate("()=>{const m=document.querySelector('#mpmap');return !!m&&m.parentElement.id=='mpbody'&&!document.querySelector('img.wxcells')}"))
        pg.click('[data-t=wx]'); pg.wait_for_timeout(1200)
        check('and the page takes it again', pg.locator('#wxbox .leaflet-container').count() == 1 and pg.locator('#wxbox img.wxcells').count() == 1)
        check('no page errors', not errs); print(errs[:3])
finally:
    srv.terminate()
print('ALL OK' if ok else 'SOME FAILED'); sys.exit(0 if ok else 1)
